SELECT compound_structures.canonical_smiles, molecule_dictionary.chembl_id, activities.standard_type, activities.standard_relation, activities.standard_value, activities.standard_units FROM activities JOIN assays ON activities.assay_id = assays.assay_id JOIN compound_structures ON activities.molregno = compound_structures.molregno JOIN molecule_dictionary ON activities.molregno = molecule_dictionary.molregno WHERE assays.chembl_id = 'CHEMBL1054502' AND activities.standard_value IS NOT NULL AND activities.standard_relation = '=' ORDER BY compound_structures.canonical_smiles ASC, molecule_dictionary.chembl_id ASC, activities.standard_type ASC, activities.standard_relation ASC, activities.standard_value ASC, activities.standard_units ASC
